<script setup>
import { onMounted, ref } from 'vue'; import { api } from '../api'; import { Activity, Database, Play, RotateCcw, TerminalSquare } from 'lucide-vue-next'
const isDemo = import.meta.env.MODE === 'demo'
const overview=ref(null),prompts=ref(null),knowledge=ref(null),jobs=ref([]),error=ref(''),busy=ref('')
async function load(){try{const [o,p,k,j]=await Promise.all([api.admin.overview(),api.admin.prompts(),api.admin.knowledge(),api.admin.jobs()]);overview.value=o;prompts.value=p;knowledge.value=k;jobs.value=j.items}catch(e){error.value=e.message}}
async function run(kind){busy.value=kind;try{const job=kind==='eval'?await api.admin.evaluate():await api.admin.reindex();jobs.value.unshift(job)}catch(e){error.value=e.message}finally{busy.value=''}}
async function activate(item){await api.admin.activatePrompt(item.task,item.version);await load()}
onMounted(load)
function percent(value){return value===null||value===undefined?'--':`${Math.round(Number(value)*100)}%`}
function primaryMode(modes){const rows=Object.entries(modes||{}).sort((a,b)=>b[1]-a[1]);return rows[0]?.[0]||'暂无样本'}
const modeLabels={recipe_catalog:'配方目录',inventory_catalog:'库存目录',local_bm25:'本地 BM25',milvus_hybrid:'Milvus 混合检索',unavailable:'不可用'}
function modeLabel(mode){return modeLabels[mode]||mode}
</script>
<template><div class="page"><header class="page-head"><div><h1>AI 控制台</h1><p>{{isDemo?'控制台界面预览。后端运行数据与运维任务在正式部署后可用。':'查看 Agent/RAG 运行状态、成本、版本和后台任务。'}}</p></div><button class="btn" @click="load"><RotateCcw :size="16"/>刷新</button></header><div v-if="error" class="error-box">{{error}}</div>
<section class="grid grid-4 metrics"><article class="panel panel-pad"><Activity :size="19"/><span>7 日调用</span><strong>{{overview?.usage?.totals?.calls||0}}</strong></article><article class="panel panel-pad"><span>累计 Token</span><strong>{{overview?.usage?.totals?.tokens||0}}</strong></article><article class="panel panel-pad"><span>成本（CNY）</span><strong>¥{{Number(overview?.usage?.totals?.cost||0).toFixed(4)}}</strong></article><article class="panel panel-pad"><Database :size="19"/><span>知识版本</span><strong>{{overview?.knowledge_versions||0}}</strong></article></section>
<section class="rag-band"><div class="rag-title"><div><small>RAG 运行证据</small><h2>检索质量与降级路径</h2></div><span>{{overview?.rag?.with_retrieval||0}} / {{overview?.rag?.samples||0}} 条回答使用检索</span></div><div class="rag-metrics"><div><small>主要模式</small><strong>{{modeLabel(primaryMode(overview?.rag?.retrieval_modes))}}</strong></div><div><small>平均置信度</small><strong>{{percent(overview?.rag?.avg_confidence)}}</strong></div><div><small>字段覆盖</small><strong>{{percent(overview?.rag?.avg_field_coverage)}}</strong></div><div><small>最近候选数</small><strong>{{overview?.rag?.recent?.[0]?.candidate_count ?? '--'}}</strong></div></div><div class="table-wrap rag-traces"><table><thead><tr><th>时间</th><th>检索模式</th><th>置信度</th><th>字段覆盖</th><th>候选</th><th>回答能力</th></tr></thead><tbody><tr v-for="item in overview?.rag?.recent||[]" :key="item.trace_id||item.created_at"><td>{{item.created_at}}</td><td>{{modeLabel(item.mode)}}</td><td>{{percent(item.confidence)}}</td><td>{{percent(item.field_coverage)}}</td><td>{{item.candidate_count ?? '--'}}</td><td>{{item.capability_mode}}</td></tr><tr v-if="!overview?.rag?.recent?.length"><td colspan="6" class="muted">{{isDemo?'部署后端后可查看检索指标。':'暂无检索样本。完成一次配方查询后会在这里出现真实指标。'}}</td></tr></tbody></table></div></section>
<section class="admin-grid"><div class="panel panel-pad"><div class="section-head"><h2 class="section-title">Prompt 版本</h2></div><div class="table-wrap"><table><thead><tr><th>任务</th><th>版本</th><th>状态</th><th>创建时间</th><th></th></tr></thead><tbody><tr v-for="item in prompts?.versions" :key="item.id"><td>{{item.task}}</td><td>{{item.version}}</td><td><span class="chip" :class="item.is_active?'green':''">{{item.is_active?'已激活':'未激活'}}</span></td><td>{{item.created_at}}</td><td><button v-if="!item.is_active" class="btn mini" @click="activate(item)">激活</button></td></tr><tr v-if="!prompts?.versions?.length"><td colspan="5" class="muted">暂无数据库 Prompt 版本，当前使用内置默认版本。</td></tr></tbody></table></div></div><aside class="panel panel-pad operations"><h2 class="section-title"><TerminalSquare :size="18"/>运维操作</h2><button class="btn primary" :disabled="isDemo || Boolean(busy)" @click="run('eval')"><Play :size="16"/>运行 RAG 评测</button><button class="btn" :disabled="isDemo || Boolean(busy)" @click="run('reindex')"><Database :size="16"/>重建知识索引</button><p>{{isDemo?'线上演示仅展示控制台界面。':'任务在后台运行，可在任务列表查看日志和结果。'}}</p></aside></section>
<section class="panel panel-pad jobs"><h2 class="section-title">后台任务</h2><div class="table-wrap"><table><thead><tr><th>类型</th><th>状态</th><th>进度</th><th>创建时间</th><th>错误</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{job.kind}}</td><td><span class="chip" :class="job.status==='succeeded'?'green':job.status==='failed'?'amber':''">{{job.status}}</span></td><td>{{Math.round((job.progress||0)*100)}}%</td><td>{{job.created_at}}</td><td>{{job.error}}</td></tr><tr v-if="!jobs.length"><td colspan="5" class="muted">还没有后台任务。</td></tr></tbody></table></div></section></div></template>
<style scoped>.metrics article{display:grid;grid-template-columns:24px 1fr;gap:4px}.metrics article svg{grid-row:1/3;color:var(--amber)}.metrics article span{font-size:11px;color:var(--muted)}.metrics article strong{font-size:24px}.rag-band{margin:18px -34px 0;padding:24px 34px;background:#18231f;color:#eef3f0}.rag-title{display:flex;justify-content:space-between;align-items:end;gap:18px}.rag-title small{color:#e7a640;font-weight:800}.rag-title h2{margin:4px 0 0;font-size:20px}.rag-title>span{font-size:11px;color:#aebdb6}.rag-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:#ffffff24;margin-top:17px}.rag-metrics>div{display:grid;gap:5px;background:#18231f;padding:14px}.rag-metrics small{color:#9fb0a8}.rag-metrics strong{font-size:17px}.rag-traces{margin-top:14px}.rag-traces th,.rag-traces td{border-color:#ffffff1a}.rag-traces th{color:#9fb0a8}.admin-grid{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:18px;margin-top:18px}.operations{display:grid;gap:10px;align-content:start}.operations .section-title{display:flex;gap:7px}.operations p{font-size:11px;color:var(--muted)}.jobs{margin-top:18px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}th,td{padding:10px;border-bottom:1px solid var(--line);white-space:nowrap}th{color:var(--muted);font-weight:600}.mini{min-height:28px;padding:0 8px;font-size:10px}@media(max-width:850px){.rag-band{margin-left:-16px;margin-right:-16px;padding:20px 16px}.rag-title{align-items:start;flex-direction:column}.rag-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.admin-grid{grid-template-columns:1fr}}</style>
